/*
 * TV PRODUCT GRID
 * ============================================================
 * Handles:
 *
 * - Product hotspot / popup opening
 * - Popup closing
 * - ESC key closing
 * - Color selection
 * - Shopify variant matching
 * - Add to Cart
 * - Automatic Soft Winter Jacket addition
 *
 * AUTOMATIC JACKET:
 *
 * Product handle:
 * dark-winter-jacket
 *
 * Required jacket variant:
 *
 * Color = Black
 * Size  = Medium
 *
 * IMPORTANT:
 *
 * The jacket variant ID is generated by Liquid in:
 *
 * #tv-soft-winter-jacket-config-SECTION_ID
 *
 * JavaScript does NOT fetch the jacket product.
 *
 * ============================================================
 */

(function () {
  'use strict';


  /*
   * ==========================================================
   * INITIALIZE PRODUCT GRID
   * ==========================================================
   */

  function initGrid(section) {

    if (!section) {
      return;
    }


    const hotspots =
      section.querySelectorAll(
        '.tv-product-hotspot'
      );


    const popups =
      section.querySelectorAll(
        '[data-popup]'
      );


    /*
     * ========================================================
     * OPEN POPUP
     * ========================================================
     */

    function openPopup(hotspot) {

      const popupId =
        hotspot.getAttribute(
          'aria-controls'
        );


      if (!popupId) {
        return;
      }


      const popup =
        document.getElementById(
          popupId
        );


      if (!popup) {
        return;
      }


      /*
       * Close all other popups.
       */

      popups.forEach(
        function (item) {

          item.classList.remove(
            'is-open'
          );

          item.setAttribute(
            'aria-hidden',
            'true'
          );

        }
      );


      /*
       * Reset all hotspot states.
       */

      hotspots.forEach(
        function (item) {

          item.setAttribute(
            'aria-expanded',
            'false'
          );

        }
      );


      /*
       * Open selected popup.
       */

      popup.classList.add(
        'is-open'
      );


      popup.setAttribute(
        'aria-hidden',
        'false'
      );


      hotspot.setAttribute(
        'aria-expanded',
        'true'
      );


      /*
       * Prevent background scrolling.
       */

      document.documentElement.classList.add(
        'tv-product-popup-open'
      );


      document.body.classList.add(
        'tv-product-popup-open'
      );

    }


    /*
     * ========================================================
     * CLOSE POPUP
     * ========================================================
     */

    function closePopup(popup) {

      if (!popup) {
        return;
      }


      popup.classList.remove(
        'is-open'
      );


      popup.setAttribute(
        'aria-hidden',
        'true'
      );


      hotspots.forEach(
        function (item) {

          item.setAttribute(
            'aria-expanded',
            'false'
          );

        }
      );


      document.documentElement.classList.remove(
        'tv-product-popup-open'
      );


      document.body.classList.remove(
        'tv-product-popup-open'
      );

    }


    /*
     * ========================================================
     * HOTSPOT CLICK
     * ========================================================
     */

    hotspots.forEach(
      function (hotspot) {

        hotspot.addEventListener(
          'click',
          function () {

            openPopup(
              hotspot
            );

          }
        );

      }
    );


    /*
     * ========================================================
     * CLOSE BUTTON / OVERLAY
     * ========================================================
     */

    popups.forEach(
      function (popup) {

        const closeElements =
          popup.querySelectorAll(
            '[data-popup-close]'
          );


        closeElements.forEach(
          function (element) {

            element.addEventListener(
              'click',
              function () {

                closePopup(
                  popup
                );

              }
            );

          }
        );

      }
    );


    /*
     * ========================================================
     * ESC KEY
     * ========================================================
     */

    document.addEventListener(
      'keydown',
      function (event) {

        if (
          event.key !== 'Escape'
        ) {
          return;
        }


        popups.forEach(
          function (popup) {

            if (
              popup.classList.contains(
                'is-open'
              )
            ) {

              closePopup(
                popup
              );

            }

          }
        );

      }
    );


    /*
     * ========================================================
     * GET SELECTED SHOPIFY VARIANT
     * ========================================================
     *
     * Finds the exact variant selected by the customer.
     *
     * It supports:
     *
     * Color + Size
     *
     * Color + Size + another option
     *
     * It first attempts to use Shopify's actual option order
     * when the option-name JSON exists.
     *
     * If that JSON is unavailable, it falls back to matching
     * the selected values against variant.options.
     *
     * ========================================================
     */

    function getSelectedVariant(form) {

      /*
       * ------------------------------------------------------
       * GET VARIANT JSON
       * ------------------------------------------------------
       */

      const variantsElement =
        form.querySelector(
          '.tv-product-popup__variants'
        );


      if (!variantsElement) {

        console.error(
          'Variant JSON not found.'
        );

        return null;

      }


      let variants;


      try {

        variants =
          JSON.parse(
            variantsElement.textContent
          );

      } catch (error) {

        console.error(
          'Unable to parse product variants:',
          error
        );

        return null;

      }


      if (
        !Array.isArray(
          variants
        )
      ) {

        console.error(
          'Product variants are not an array.',
          variants
        );

        return null;

      }


      /*
       * ------------------------------------------------------
       * GET SHOPIFY OPTION NAMES
       * ------------------------------------------------------
       */

      let optionNames = null;


      const optionNamesElement =
        form.querySelector(
          '.tv-product-popup__option-names'
        );


      if (optionNamesElement) {

        try {

          optionNames =
            JSON.parse(
              optionNamesElement.textContent
            );

        } catch (error) {

          console.warn(
            'Unable to parse product option names. Using fallback matching.'
          );

        }

      }


      /*
       * ------------------------------------------------------
       * BUILD CUSTOMER SELECTIONS
       * ------------------------------------------------------
       */

      const selections = {};


      /*
       * COLOR
       */

      const activeColor =
        form.querySelector(
          '.tv-product-popup__color.active'
        );


      if (activeColor) {

        selections.Color =
          String(
            activeColor.dataset.color || ''
          ).trim();

      }


      /*
       * OTHER OPTIONS
       */

      const selects =
        form.querySelectorAll(
          '.tv-product-popup__select'
        );


      selects.forEach(
        function (select) {

          const optionName =
            select.dataset.optionName;


          if (!optionName) {
            return;
          }


          selections[optionName] =
            String(
              select.value || ''
            ).trim();

        }
      );


      console.log(
        'CUSTOMER SELECTIONS:',
        selections
      );


      /*
       * ------------------------------------------------------
       * CHECK FOR MISSING SELECTIONS
       * ------------------------------------------------------
       *
       * Only validate options that actually have controls
       * in the popup.
       *
       * ------------------------------------------------------
       */

      const selectedOptionNames =
        Object.keys(
          selections
        );


      if (
        selectedOptionNames.length === 0
      ) {

        console.error(
          'No product options have been selected.'
        );

        return null;

      }


      for (
        let i = 0;
        i < selectedOptionNames.length;
        i++
      ) {

        const optionName =
          selectedOptionNames[i];


        const value =
          selections[
            optionName
          ];


        if (!value) {

          console.warn(
            'Missing product option:',
            optionName
          );

          return null;

        }

      }


      /*
       * ------------------------------------------------------
       * MATCH USING SHOPIFY OPTION ORDER
       * ------------------------------------------------------
       *
       * If .tv-product-popup__option-names exists, use:
       *
       * product.options
       *
       * Example:
       *
       * ["Color", "Size"]
       *
       * Variant:
       *
       * option1 = Black
       * option2 = Medium
       *
       * ------------------------------------------------------
       */

      if (
        Array.isArray(
          optionNames
        ) &&
        optionNames.length > 0
      ) {

        console.log(
          'SHOPIFY OPTION ORDER:',
          optionNames
        );


        const exactVariant =
          variants.find(
            function (variant) {

              /*
               * Only available variants.
               */

              if (
                variant.available === false
              ) {

                return false;

              }


              /*
               * Check every selected option.
               */

              return selectedOptionNames.every(
                function (selectedOptionName) {

                  const optionIndex =
                    optionNames.findIndex(
                      function (name) {

                        return (
                          String(name)
                            .trim()
                            .toLowerCase() ===
                          String(
                            selectedOptionName
                          )
                            .trim()
                            .toLowerCase()
                        );

                      }
                    );


                  /*
                   * Option name was not found.
                   */

                  if (
                    optionIndex === -1
                  ) {

                    return false;

                  }


                  const variantValue =
                    variant[
                      'option' +
                      (optionIndex + 1)
                    ];


                  const selectedValue =
                    selections[
                      selectedOptionName
                    ];


                  if (
                    variantValue ===
                      null ||
                    variantValue ===
                      undefined
                  ) {

                    return false;

                  }


                  return (
                    String(
                      variantValue
                    )
                      .trim()
                      .toLowerCase() ===
                    String(
                      selectedValue
                    )
                      .trim()
                      .toLowerCase()
                  );

                }
              );

            }
          );


        if (exactVariant) {

          console.log(
            'EXACT SHOPIFY VARIANT FOUND:',
            exactVariant
          );


          return exactVariant;

        }

      }


      /*
       * ------------------------------------------------------
       * FALLBACK VARIANT MATCHING
       * ------------------------------------------------------
       *
       * This is useful if the option-name JSON isn't present
       * or if the product data differs from expected.
       *
       * We compare all selected values against the variant's
       * option values without depending on their order.
       *
       * ------------------------------------------------------
       */

      const selectedValues =
        Object.values(
          selections
        )
          .map(
            function (value) {

              return String(
                value
              )
                .trim()
                .toLowerCase();

            }
          );


      console.log(
        'FALLBACK SELECTED VALUES:',
        selectedValues
      );


      const fallbackVariant =
        variants.find(
          function (variant) {

            if (
              variant.available === false
            ) {

              return false;

            }


            const variantOptions = [
              variant.option1,
              variant.option2,
              variant.option3
            ]
              .filter(
                function (value) {

                  return (
                    value !== null &&
                    value !== undefined &&
                    value !== ''
                  );

                }
              )
              .map(
                function (value) {

                  return String(
                    value
                  )
                    .trim()
                    .toLowerCase();

                }
              );


            /*
             * Every selected value must exist in the
             * variant's options.
             */

            return selectedValues.every(
              function (selectedValue) {

                return variantOptions.includes(
                  selectedValue
                );

              }
            );

          }
        );


      console.log(
        'FALLBACK MATCHED VARIANT:',
        fallbackVariant
      );


      return (
        fallbackVariant ||
        null
      );

    }


    /*
     * ========================================================
     * COLOR SELECTION
     * ========================================================
     */

    section
      .querySelectorAll(
        '.tv-product-popup__colors'
      )
      .forEach(
        function (group) {

          const buttons =
            group.querySelectorAll(
              '.tv-product-popup__color'
            );


          buttons.forEach(
            function (button) {

              button.addEventListener(
                'click',
                function () {

                  buttons.forEach(
                    function (btn) {

                      btn.classList.remove(
                        'active'
                      );

                    }
                  );


                  button.classList.add(
                    'active'
                  );


                  console.log(
                    'SELECTED COLOR:',
                    button.dataset.color
                  );

                }
              );

            }
          );

        }
      );


    /*
     * ========================================================
     * ADD ITEMS TO SHOPIFY CART
     * ========================================================
     *
     * Shopify supports multiple variants in one request:
     *
     * POST /cart/add.js
     *
     * {
     *   items: [
     *     { id: 123, quantity: 1 },
     *     { id: 456, quantity: 1 }
     *   ]
     * }
     *
     * ========================================================
     */

    async function addToCart(items) {

      console.log(
        'ADDING ITEMS TO SHOPIFY CART:',
        items
      );


      const response =
        await fetch(
          window.Shopify.routes.root +
          'cart/add.js',
          {
            method: 'POST',

            headers: {
              'Content-Type':
                'application/json',

              'Accept':
                'application/json'
            },

            body: JSON.stringify({
              items: items
            })
          }
        );


      if (!response.ok) {

        let errorData = null;


        try {

          errorData =
            await response.json();

        } catch (error) {

          console.error(
            'Unable to parse Shopify cart error:',
            error
          );

        }


        console.error(
          'SHOPIFY CART ERROR:',
          errorData
        );


        throw new Error(
          errorData?.description ||
          errorData?.message ||
          'Unable to add product to cart.'
        );

      }


      const data =
        await response.json();


      console.log(
        'SHOPIFY CART RESPONSE:',
        data
      );


      return data;

    }


    /*
     * ========================================================
     * GET SOFT WINTER JACKET VARIANT
     * ========================================================
     *
     * IMPORTANT:
     *
     * The exact jacket variant ID is generated by Liquid.
     *
     * Liquid searches the product:
     *
     * dark-winter-jacket
     *
     * and finds:
     *
     * Black
     * Medium
     * Available
     *
     * JavaScript simply reads that exact variant ID.
     *
     * ========================================================
     */

    function getSoftWinterJacketVariant(
      section
    ) {

      const sectionId =
        section.dataset.sectionId;


      if (!sectionId) {

        console.error(
          'TV Product Grid section ID is missing.'
        );


        throw new Error(
          'Product grid section ID is missing.'
        );

      }


      const configId =
        'tv-soft-winter-jacket-config-' +
        sectionId;


      const configElement =
        document.getElementById(
          configId
        );


      if (!configElement) {

        console.error(
          'Soft Winter Jacket configuration was not found.',
          configId
        );


        throw new Error(
          'Soft Winter Jacket configuration was not found.'
        );

      }


      let config;


      try {

        config =
          JSON.parse(
            configElement.textContent
          );

      } catch (error) {

        console.error(
          'Unable to parse Soft Winter Jacket configuration:',
          error
        );


        throw new Error(
          'Unable to read Soft Winter Jacket configuration.'
        );

      }


      console.log(
        'SOFT WINTER JACKET CONFIG:',
        config
      );


      /*
       * Product does not exist.
       */

      if (
        !config.productFound
      ) {

        throw new Error(
          'Soft Winter Jacket product was not found.'
        );

      }


      /*
       * Black + Medium variant does not exist
       * or is unavailable.
       */

      if (
        !config.variantId
      ) {

        throw new Error(
          'The Black + Medium Soft Winter Jacket variant is unavailable.'
        );

      }


      const jacketVariantId =
        Number(
          config.variantId
        );


      if (
        !Number.isFinite(
          jacketVariantId
        ) ||
        jacketVariantId <= 0
      ) {

        console.error(
          'Invalid Soft Winter Jacket variant ID:',
          config.variantId
        );


        throw new Error(
          'Invalid Soft Winter Jacket variant ID.'
        );

      }


      console.log(
        'FOUND SOFT WINTER JACKET VARIANT ID:',
        jacketVariantId
      );


      return jacketVariantId;

    }


    /*
     * ========================================================
     * ADD TO CART BUTTON
     * ========================================================
     */

    section
      .querySelectorAll(
        '.tv-product-popup__add'
      )
      .forEach(
        function (button) {

          button.addEventListener(
            'click',
            async function () {

              /*
               * ------------------------------------------------
               * GET FORM
               * ------------------------------------------------
               */

              const form =
                button.closest(
                  '.tv-product-popup__form'
                );


              if (!form) {

                console.error(
                  'Product popup form not found.'
                );

                return;

              }


              /*
               * ------------------------------------------------
               * GET SELECTED PRODUCT VARIANT
               * ------------------------------------------------
               */

              const variant =
                getSelectedVariant(
                  form
                );


              if (!variant) {

                alert(
                  'Please select a color and size.'
                );

                return;

              }


              /*
               * ------------------------------------------------
               * CHECK VARIANT AVAILABILITY
               * ------------------------------------------------
               */

              if (
                variant.available === false
              ) {

                alert(
                  'This variant is currently unavailable.'
                );

                return;

              }


              /*
               * ------------------------------------------------
               * PREVENT DOUBLE CLICK
               * ------------------------------------------------
               */

              button.disabled = true;


              const originalText =
                button.querySelector(
                  'span'
                );


              if (originalText) {

                originalText.textContent =
                  'ADDING...';

              }


              try {

                /*
                 * ------------------------------------------------
                 * START WITH SELECTED PRODUCT
                 * ------------------------------------------------
                 */

                const cartItems = [
                  {
                    id: Number(
                      variant.id
                    ),

                    quantity: 1
                  }
                ];


                /*
                 * ------------------------------------------------
                 * GET ACTUAL SELECTED VARIANT OPTIONS
                 * ------------------------------------------------
                 */

                const variantOptions = [
                  variant.option1,
                  variant.option2,
                  variant.option3
                ]
                  .filter(
                    function (value) {

                      return (
                        value !== null &&
                        value !== undefined &&
                        value !== ''
                      );

                    }
                  )
                  .map(
                    function (value) {

                      return String(
                        value
                      )
                        .trim()
                        .toLowerCase();

                    }
                  );


                console.log(
                  '========================================'
                );


                console.log(
                  'SELECTED PRODUCT VARIANT:',
                  variant
                );


                console.log(
                  'SELECTED PRODUCT OPTIONS:',
                  variantOptions
                );


                /*
                 * ------------------------------------------------
                 * CHECK BLACK
                 * ------------------------------------------------
                 */

                const hasBlack =
                  variantOptions.includes(
                    'black'
                  );


                /*
                 * ------------------------------------------------
                 * CHECK MEDIUM
                 * ------------------------------------------------
                 */

                const hasMedium =
                  variantOptions.includes(
                    'medium'
                  );


                /*
                 * ------------------------------------------------
                 * FINAL TRIGGER
                 * ------------------------------------------------
                 */

                const isBlackMedium =
                  hasBlack &&
                  hasMedium;


                console.log(
                  'HAS BLACK:',
                  hasBlack
                );


                console.log(
                  'HAS MEDIUM:',
                  hasMedium
                );


                console.log(
                  'BLACK + MEDIUM TRIGGER:',
                  isBlackMedium
                );


                /*
                 * ------------------------------------------------
                 * AUTOMATICALLY ADD JACKET
                 * ------------------------------------------------
                 */

                if (
                  isBlackMedium
                ) {

                  console.log(
                    '========================================'
                  );


                  console.log(
                    'BLACK + MEDIUM DETECTED'
                  );


                  console.log(
                    'LOOKING FOR SOFT WINTER JACKET...'
                  );


                  const jacketVariantId =
                    getSoftWinterJacketVariant(
                      section
                    );


                  console.log(
                    'SOFT WINTER JACKET VARIANT ID:',
                    jacketVariantId
                  );


                  /*
                   * Add jacket to the same cart request.
                   */

                  cartItems.push(
                    {
                      id:
                        jacketVariantId,

                      quantity: 1
                    }
                  );


                  console.log(
                    'SOFT WINTER JACKET ADDED TO REQUEST'
                  );


                } else {

                  console.log(
                    'BLACK + MEDIUM NOT DETECTED.'
                  );


                  console.log(
                    'NO AUTOMATIC JACKET WILL BE ADDED.'
                  );

                }


                /*
                 * ------------------------------------------------
                 * FINAL CART ITEMS
                 * ------------------------------------------------
                 */

                console.log(
                  'FINAL CART ITEMS:',
                  cartItems
                );


                /*
                 * ------------------------------------------------
                 * SEND ONE CART REQUEST
                 * ------------------------------------------------
                 */

                const cart =
                  await addToCart(
                    cartItems
                  );


                console.log(
                  'CART SUCCESSFULLY UPDATED:',
                  cart
                );


                /*
                 * ------------------------------------------------
                 * BUTTON FEEDBACK
                 * ------------------------------------------------
                 */

                if (originalText) {

                  originalText.textContent =
                    'ADDED TO CART';

                }


                /*
                 * ------------------------------------------------
                 * REDIRECT TO CART
                 * ------------------------------------------------
                 */

                window.location.href =
                  '/cart';


              } catch (error) {

                console.error(
                  '========================================'
                );


                console.error(
                  'ADD TO CART FAILED:',
                  error
                );


                console.error(
                  '========================================'
                );


                alert(
                  error.message ||
                  'Unable to add product to cart.'
                );


                if (originalText) {

                  originalText.textContent =
                    'ADD TO CART';

                }

              } finally {

                button.disabled =
                  false;

              }

            }
          );

        }
      );

  }


  /*
   * ==========================================================
   * INITIALIZE ALL PRODUCT GRID SECTIONS
   * ==========================================================
   */

  function initializeProductGrids() {

    const sections =
      document.querySelectorAll(
        '.tv-product-grid'
      );


    console.log(
      'TV PRODUCT GRID SECTIONS FOUND:',
      sections.length
    );


    sections.forEach(
      function (section) {

        initGrid(
          section
        );

      }
    );

  }


  /*
   * ==========================================================
   * START
   * ==========================================================
   */

  if (
    document.readyState ===
    'loading'
  ) {

    document.addEventListener(
      'DOMContentLoaded',
      initializeProductGrids
    );

  } else {

    initializeProductGrids();

  }

})();
